import{_ as i,o as d,c as t,a2 as c}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"设备 (Device)","description":"","frontmatter":{},"headers":[],"relativePath":"device.md","filePath":"device.md","lastUpdated":1780845803000}'),o={name:"device.md"};function l(a,e,n,u,p,r){return d(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="设备-device" tabindex="-1">设备 (Device)</h1><h2 id="_6-7-0-源码校对" tabindex="-1">6.7.0 源码校对</h2><p>本页已按 AutoJs6 <code>6.7.0</code> (<code>ed3eb10e88db5a8425fd94bdddefa4176e5e1c94</code>) 对照以下源码路径校对:</p><ul><li><code>app/src/main/java/org/autojs/autojs/runtime/ScriptRuntime.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/augment/device/Device.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/Device.java</code></li></ul><p>运行时中 <code>device</code> / <code>$device</code> 由 augment 注入. 基础 <code>Device.java</code> 提供设备信息、屏幕、亮度、音量、电池、内存、唤醒 / 熄屏、震动、方向、网络和部分硬件标识读取能力; augment 层补充当前 AutoJs6 运行时便捷函数.</p><p>当前 augment 公开函数包括 <code>summary</code>, <code>digest</code>, <code>vibrate</code>, <code>isScreenOff</code>, <code>isScreenPortrait</code>, <code>isScreenLandscape</code>, <code>getIpAddress</code>, <code>getIpv6Address</code>, <code>getGatewayAddress</code>, 网络状态检查, <code>getSharedDeviceId</code>, 指针位置相关函数. getter 包括 <code>width</code>, <code>height</code>, <code>rotation</code>, <code>orientation</code>, <code>density</code>.</p><p><code>vibrate</code> 支持毫秒数、摩斯字符串、震动时间数组等形式; 两参数形式可表达字符串选项、关闭 / 持续时间或数组 pattern 的 repeat/off 参数.</p><p>亮度、音量、指针位置等系统设置相关能力受 Android 权限和系统版本限制. Android API 23+ 不能再通过私有 <code>Settings.System</code> 字段直接修改指针位置, 当前实现改由 <code>PointerLocationTool</code> 处理.</p><p>device模块提供了与设备有关的信息与操作, 例如获取设备宽高, 内存使用率, IMEI, 调整设备亮度、音量等.</p><p>此模块的部分函数, 例如调整音量, 需要&quot;修改系统设置&quot;的权限. 如果没有该权限, 会抛出<code>SecurityException</code>并跳转到权限设置界面.</p><h2 id="device-width" tabindex="-1">device.width</h2><ul><li>{number}</li></ul><p>设备屏幕分辨率宽度. 例如1080.</p><h2 id="device-height" tabindex="-1">device.height</h2><ul><li>{number}</li></ul><p>设备屏幕分辨率高度. 例如1920.</p><h2 id="device-buildid" tabindex="-1">device.buildId</h2><ul><li>{string}</li></ul><p>Either a changelist number, or a label like &quot;M4-rc20&quot;.</p><p>修订版本号, 或者诸如&quot;M4-rc20&quot;的标识.</p><h2 id="device-broad" tabindex="-1">device.broad</h2><ul><li>{string}</li></ul><p>The name of the underlying board, like &quot;goldfish&quot;.</p><p>设备的主板(?)型号.</p><h2 id="device-brand" tabindex="-1">device.brand</h2><ul><li>{string}</li></ul><p>The consumer-visible brand with which the product/hardware will be associated, if any.</p><p>与产品或硬件相关的厂商品牌, 如&quot;Xiaomi&quot;, &quot;Huawei&quot;等.</p><h2 id="device-device" tabindex="-1">device.device</h2><ul><li>{string}</li></ul><p>The name of the industrial design.</p><p>设备在工业设计中的名称.</p><h2 id="device-model" tabindex="-1">device.model</h2><ul><li>{string}</li></ul><p>The end-user-visible name for the end product.</p><p>设备型号.</p><h2 id="device-product" tabindex="-1">device.product</h2><ul><li>{string}</li></ul><p>The name of the overall product.</p><p>整个产品的名称.</p><h2 id="device-bootloader" tabindex="-1">device.bootloader</h2><ul><li>{string}</li></ul><p>The system bootloader version number.</p><p>设备Bootloader的版本.</p><h2 id="device-hardware" tabindex="-1">device.hardware</h2><ul><li>{string}</li></ul><p>The name of the hardware (from the kernel command line or /proc).</p><p>设备的硬件名称(来自内核命令行或者/proc).</p><h2 id="device-fingerprint" tabindex="-1">device.fingerprint</h2><ul><li>{string}</li></ul><p>A string that uniquely identifies this build. Do not attempt to parse this value.</p><p>构建(build)的唯一标识码.</p><h2 id="device-serial" tabindex="-1">device.serial</h2><ul><li>{string}</li></ul><p>A hardware serial number, if available. Alphanumeric only, case-insensitive.</p><p>硬件序列号.</p><h2 id="device-sdkint" tabindex="-1">device.sdkInt</h2><ul><li>{number}</li></ul><p>The user-visible SDK version of the framework; its possible values are defined in Build.VERSION_CODES.</p><p>安卓系统API版本. 例如安卓4.4的sdkInt为19.</p><h2 id="device-incremental" tabindex="-1">device.incremental</h2><ul><li>{string}</li></ul><p>The internal value used by the underlying source control to represent this build. E.g., a perforce changelist number or a git hash.</p><h2 id="device-release" tabindex="-1">device.release</h2><ul><li>{string}</li></ul><p>The user-visible version string. E.g., &quot;1.0&quot; or &quot;3.4b5&quot;.</p><p>Android系统版本号. 例如&quot;5.0&quot;, &quot;7.1.1&quot;.</p><h2 id="device-baseos" tabindex="-1">device.baseOS</h2><ul><li>{string}</li></ul><p>The base OS build the product is based on.</p><h2 id="device-securitypatch" tabindex="-1">device.securityPatch</h2><ul><li>{string}</li></ul><p>The user-visible security patch level.</p><p>安全补丁程序级别.</p><h2 id="device-codename" tabindex="-1">device.codename</h2><ul><li>{string}</li></ul><p>The current development codename, or the string &quot;REL&quot; if this is a release build.</p><p>开发代号, 例如发行版是&quot;REL&quot;.</p><h2 id="device-getimei" tabindex="-1">device.getIMEI()</h2><ul><li>{string}</li></ul><p>返回设备的IMEI.</p><h2 id="device-getandroidid" tabindex="-1">device.getAndroidId()</h2><ul><li>{string}</li></ul><p>返回设备的Android ID.</p><p>Android ID为一个用16进制字符串表示的64位整数, 在设备第一次使用时随机生成, 之后不会更改, 除非恢复出厂设置.</p><h2 id="device-getmacaddress" tabindex="-1">device.getMacAddress()</h2><ul><li>{string}</li></ul><p>返回设备的Mac地址. 该函数需要在有WLAN连接的情况下才能获取, 否则会返回null.</p><p><strong>可能的后续修改</strong>：未来可能增加有root权限的情况下通过root权限获取, 从而在没有WLAN连接的情况下也能返回正确的Mac地址, 因此请勿使用此函数判断WLAN连接.</p><h2 id="device-getbrightness" tabindex="-1">device.getBrightness()</h2><ul><li>{number}</li></ul><p>返回当前的(手动)亮度. 范围为0~255.</p><h2 id="device-getbrightnessmode" tabindex="-1">device.getBrightnessMode()</h2><ul><li>{number}</li></ul><p>返回当前亮度模式, 0为手动亮度, 1为自动亮度.</p><h2 id="device-setbrightness-b" tabindex="-1">device.setBrightness(b)</h2><ul><li><code>b</code> {number} 亮度, 范围0~255</li></ul><p>设置当前手动亮度. 如果当前是自动亮度模式, 该函数不会影响屏幕的亮度.</p><p>此函数需要&quot;修改系统设置&quot;的权限. 如果没有该权限, 会抛出SecurityException并跳转到权限设置界面.</p><h2 id="device-setbrightnessmode-mode" tabindex="-1">device.setBrightnessMode(mode)</h2><ul><li><code>mode</code> {number} 亮度模式, 0为手动亮度, 1为自动亮度</li></ul><p>设置当前亮度模式.</p><p>此函数需要&quot;修改系统设置&quot;的权限. 如果没有该权限, 会抛出SecurityException并跳转到权限设置界面.</p><h2 id="device-getmusicvolume" tabindex="-1">device.getMusicVolume()</h2><ul><li>{number} 整数值</li></ul><p>返回当前媒体音量.</p><h2 id="device-getnotificationvolume" tabindex="-1">device.getNotificationVolume()</h2><ul><li>{number} 整数值</li></ul><p>返回当前通知音量.</p><h2 id="device-getalarmvolume" tabindex="-1">device.getAlarmVolume()</h2><ul><li>{number} 整数值</li></ul><p>返回当前闹钟音量.</p><h2 id="device-getmusicmaxvolume" tabindex="-1">device.getMusicMaxVolume()</h2><ul><li>{number} 整数值</li></ul><p>返回媒体音量的最大值.</p><h2 id="device-getnotificationmaxvolume" tabindex="-1">device.getNotificationMaxVolume()</h2><ul><li>{number} 整数值</li></ul><p>返回通知音量的最大值.</p><h2 id="device-getalarmmaxvolume" tabindex="-1">device.getAlarmMaxVolume()</h2><ul><li>{number} 整数值</li></ul><p>返回闹钟音量的最大值.</p><h2 id="device-setmusicvolume-volume" tabindex="-1">device.setMusicVolume(volume)</h2><ul><li><code>volume</code> {number} 音量</li></ul><p>设置当前媒体音量.</p><p>此函数需要&quot;修改系统设置&quot;的权限. 如果没有该权限, 会抛出SecurityException并跳转到权限设置界面.</p><h2 id="device-setnotificationvolume-volume" tabindex="-1">device.setNotificationVolume(volume)</h2><ul><li><code>volume</code> {number} 音量</li></ul><p>设置当前通知音量.</p><p>此函数需要&quot;修改系统设置&quot;的权限. 如果没有该权限, 会抛出SecurityException并跳转到权限设置界面.</p><h2 id="device-setalarmvolume-volume" tabindex="-1">device.setAlarmVolume(volume)</h2><ul><li><code>volume</code> {number} 音量</li></ul><p>设置当前闹钟音量.</p><p>此函数需要&quot;修改系统设置&quot;的权限. 如果没有该权限, 会抛出SecurityException并跳转到权限设置界面.</p><h2 id="device-getbattery" tabindex="-1">device.getBattery()</h2><ul><li>{number} 0.0~100.0的浮点数</li></ul><p>返回当前电量百分比.</p><h2 id="device-ischarging" tabindex="-1">device.isCharging()</h2><ul><li>{boolean}</li></ul><p>返回设备是否正在充电.</p><h2 id="device-gettotalmem" tabindex="-1">device.getTotalMem()</h2><ul><li>{number}</li></ul><p>返回设备内存总量, 单位字节(B). 1MB = 1024 * 1024B.</p><h2 id="device-getavailmem" tabindex="-1">device.getAvailMem()</h2><ul><li>{number}</li></ul><p>返回设备当前可用的内存, 单位字节(B).</p><h2 id="device-isscreenon" tabindex="-1">device.isScreenOn()</h2><ul><li>返回 {boolean}</li></ul><p>返回设备屏幕是否是亮着的. 如果屏幕亮着, 返回<code>true</code>; 否则返回<code>false</code>.</p><p>需要注意的是, 类似于vivo xplay系列的息屏时钟不属于&quot;屏幕亮着&quot;的情况, 虽然屏幕确实亮着但只能显示时钟而且不可交互, 此时<code>isScreenOn()</code>也会返回<code>false</code>.</p><h2 id="device-wakeup" tabindex="-1">device.wakeUp()</h2><p>唤醒设备. 包括唤醒设备CPU、屏幕等. 可以用来点亮屏幕.</p><h2 id="device-wakeupifneeded" tabindex="-1">device.wakeUpIfNeeded()</h2><p>如果屏幕没有点亮, 则唤醒设备.</p><h2 id="device-keepscreenon-timeout" tabindex="-1">device.keepScreenOn([timeout])</h2><ul><li><code>timeout</code> {number} 屏幕保持常亮的时间, 单位毫秒. 如果不加此参数, 则一直保持屏幕常亮.</li></ul><p>保持屏幕常亮.</p><p>此函数无法阻止用户使用锁屏键等正常关闭屏幕, 只能使得设备在无人操作的情况下保持屏幕常亮；同时, 如果此函数调用时屏幕没有点亮, 则会唤醒屏幕.</p><p>在某些设备上, 如果不加参数timeout, 只能在Auto.js的界面保持屏幕常亮, 在其他界面会自动失效, 这是因为设备的省电策略造成的. 因此, 建议使用比较长的时长来代替&quot;一直保持屏幕常亮&quot;的功能, 例如<code>device.keepScreenOn(3600 * 1000)</code>.</p><p>可以使用<code>device.cancelKeepingAwake()</code>来取消屏幕常亮.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//一直保持屏幕常亮</span></span>
<span class="line"><span>device.keepScreenOn()</span></span></code></pre></div><h2 id="device-keepscreendim-timeout" tabindex="-1">device.keepScreenDim([timeout])</h2><ul><li><code>timeout</code> {number} 屏幕保持常亮的时间, 单位毫秒. 如果不加此参数, 则一直保持屏幕常亮.</li></ul><p>保持屏幕常亮, 但允许屏幕变暗来节省电量. 此函数可以用于定时脚本唤醒屏幕操作, 不需要用户观看屏幕, 可以让屏幕变暗来节省电量.</p><p>此函数无法阻止用户使用锁屏键等正常关闭屏幕, 只能使得设备在无人操作的情况下保持屏幕常亮；同时, 如果此函数调用时屏幕没有点亮, 则会唤醒屏幕.</p><p>可以使用<code>device.cancelKeepingAwake()</code>来取消屏幕常亮.</p><h2 id="device-cancelkeepingawake" tabindex="-1">device.cancelKeepingAwake()</h2><p>取消设备保持唤醒状态. 用于取消<code>device.keepScreenOn()</code>, <code>device.keepScreenDim()</code>等函数设置的屏幕常亮.</p><h2 id="device-vibrate-millis" tabindex="-1">device.vibrate(millis)</h2><ul><li><code>millis</code> {number} 振动时间, 单位毫秒</li></ul><p>使设备振动一段时间.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//振动两秒</span></span>
<span class="line"><span>device.vibrate(2000);</span></span></code></pre></div><h2 id="device-cancelvibration" tabindex="-1">device.cancelVibration()</h2><p>如果设备处于振动状态, 则取消振动.</p>`,173)])])}const v=i(o,[["render",l]]);export{h as __pageData,v as default};
